const startedAt = Date.now();
const backoffs = cfg.backoff_schedule_seconds ?? [];

for (let attempt = 0; attempt <= cfg.max_retries; attempt++) {
  const elapsed = Date.now() - startedAt;
  const remaining = totalBudgetMs - elapsed;

  if (remaining <= 0) {
    throw new Error("request deadline exceeded before next attempt");
  }

  try {
    const res = await httpRequest({
      ...opts,
      timeoutMs: remaining, // cap this attempt by remaining budget
    });
    return res;
  } catch (err) {
    if (attempt === cfg.max_retries) throw err;

    const backoffMs = (backoffs[attempt] ?? 0) * 1000;
    if (backoffMs >= remaining) {
      throw new Error("insufficient time remaining for retry backoff");
    }

    await sleep(backoffMs);
  }
}
```

