A clean Jest pattern is to mock the transport layer and assert call count plus the thrown error. Since the config is already wired with `retries: 3`, the expectation should be 4 total calls.

Here’s a compact example:

```ts
import { apiClient } from "../src/client";
import { transport } from "../src/client/http/transport";

jest.mock("../src/client/http/transport");

describe("api client retry behavior", () => {
  it("retries 3 times on 503 and then throws the last error", async () => {
    const err = Object.assign(new Error("Service Unavailable"), {
      status: 503,
      response: { status: 503, body: "upstream unavailable" },
    });

    (transport as jest.Mock).mockRejectedValue(err);

    await expect(apiClient.get("/health")).rejects.toMatchObject({
      status: 503,
      response: { status: 503, body: "upstream unavailable" },
    });

    expect(transport).toHaveBeenCalledTimes(4);
  });
});
```

